"""Networking Goodway curriculum modules 00–55 (command-heavy)."""

from __future__ import annotations

MODULES: list[dict] = []


def add(
    n,
    slug,
    title,
    phase,
    days,
    objectives,
    body,
    pitfalls,
    checks,
    reading,
    ex_kind,
    exercise_guide="",
    exercise_examples="",
):
    MODULES.append(
        dict(
            n=n,
            slug=f"{n:02d}-{slug}",
            title=title,
            phase=phase,
            days=days,
            objectives=objectives,
            body=body,
            pitfalls=pitfalls,
            checks=checks,
            reading=reading,
            ex_kind=ex_kind,
            exercise_guide=exercise_guide,
            exercise_examples=exercise_examples,
        )
    )

